// Lock-free queue implementation using MSNBC
class Node {
  price: number;
  volume: number;
  next: Node | null;
  constructor(price: number, volume: number) {
    this.price = price;
    this.volume = volume;
    this.next = null;
  }
}

class LockFreeQueue {
  private queue: Node[];
  private capacity: number;
  private spinlock: number;
  private head: number;
  private tail: number;

  constructor(capacity: number) {
    this.queue = new Array(capacity);
    this.capacity = capacity;
    this.spinlock = 0;
    this.head = 0;
    this.tail = 0;
  }

  enqueue(price: number, volume: number): void {
    const node = new Node(price, volume);
    while (true) {
      const tail = this.tail;
      if (tail === this.head || this.queue[tail] === null) {
        this.queue[tail] = node;
        if (tail === this.capacity - 1) {
          this.tail = 0;
        } else {
          this.tail++;
        }
        break;
      }
      this.spinlock = futexWait(this.spinlock);
    }
  }

  dequeue(): Node | null {
    while (true) {
      const head = this.head;
      if (this.queue[head] !== null) {
        const node = this.queue[head];
        this.queue[head] = null;
        if (head === this.capacity - 1) {
          this.head = 0;
        } else {
          this.head++;
        }
        return node;
      }
      this.spinlock = futexWait(this.spinlock);
    }
  }
}

// Example usage
const queue = new LockFreeQueue(1000);
queue.enqueue(10.0, 100);
queue.enqueue(20.0, 200);
const node = queue.dequeue();
console.log(node.price, node.volume);

