// High-performance order book data structure
class OrderBook {
  private order_book: Map<number, Map<number, number>>;
  private price_levels: number[];
  private price_to_volume: Map<number, number);

  constructor() {
    this.order_book = new Map();
    this.price_levels = [1000, 500, 200];
    this.price_to_volume = new Map();
  }

  insert(price: number, volume: number): void {
    const price_level = this.getPriceLevel(price);
    const volume_map = this.order_book.get(price_level);
    if (volume_map === undefined) {
      volume_map = new Map();
      this.order_book.set(price_level, volume_map);
    }
    volume_map.set(volume, 1);
    this.price_to_volume.set(price, volume);
  }

  delete(price: number, volume: number): void {
    const price_level = this.getPriceLevel(price);
    const volume_map = this.order_book.get(price_level);
    if (volume_map !== undefined) {
      volume_map.delete(volume);
      if (volume_map.size === 0) {
        this.order_book.delete(price_level);
      }
    }
    this.price_to_volume.delete(price);
  }

  lookup(price: number): number | null {
    const volume_map = this.order_book.get(this.getPriceLevel(price));
    if (volume_map !== undefined) {
      return this.price_to_volume.get(price);
    }
    return null;
  }

  getPriceLevel(price: number): number {
    for (const level of this.price_levels) {
      if (price <= level) {
        return level;
      }
    }
    return this.price_levels[this.price_levels.length - 1];
  }
}

// Example usage
const order_book = new OrderBook();
order_book.insert(10.0, 100);
order_book.insert(20.0, 200);
const volume = order_book.lookup(10.0);
console.log(volume);

