fn paxos_prepare(proposer: &mut Paxos, value: i32) -> Result<i32, String> {
    // Phase 1: Prepare
    let ballot = proposer.get_ballot_number() + 1;
    let prepare_msg = PrepareMsg {
        ballot,
        value,
    };
    proposer.send_prepare(prepare_msg);
    let responses = proposer.recv_prepare_responses();

    // Phase 2: Accept
    let accept_msg = AcceptMsg {
        ballot,
        value,
    };
    proposer.send_accept(accept_msg);
    let accept_responses = proposer.recv_accept_responses();

    // Handle failed nodes
    if responses.len() > 2 { // majority
        return Ok(value);
    } else {
        return Err("Failed to agree on value");
    }
}
