fn bft_consensus(block: Block) -> Result<(), String> {
    // Pre-prepare phase
    let pre_prepare_msg = PrePrepareMsg {
        block,
    };
    let pre_prepare_responses = send_pre_prepare(pre_prepare_msg);

    // Prepare phase
    let prepare_msg = PrepareMsg {
        block,
    };
    let prepare_responses = send_prepare(prepare_msg);

    // Commit phase
    let commit_msg = CommitMsg {
        block,
    };
    let commit_responses = send_commit(commit_msg);

    // Finalize phase
    let finalize_msg = FinalizeMsg {
        block,
    };
    let finalize_responses = send_finalize(finalize_msg);

    // Handle malicious nodes
    if prepare_responses.len() < 2 { // less than majority
        return Err("Failed to agree on block");
    } else if commit_responses.len() < 2 { // less than majority
        return Err("Failed to commit block");
    } else {
        return Ok(());
    }
}
